import java.util.*;

class Solution {
  public long maximumTotalCost(int[] nums) {
    long positive = nums[0], negative = Long.MIN_VALUE / 4;
    for (int i = 1; i < nums.length; i++) {
      long nextPositive = Math.max(positive, negative) + nums[i];
      long nextNegative = positive - nums[i];
      positive = nextPositive;
      negative = nextNegative;
    }
    return Math.max(positive, negative);
  }
}
